    {
      "element_id": "prisma_2020_4_e1",
      "status": "MISSING",
      "chunk_id": "text_2",
      "quote": "System dynamics modeling... is being increasingly applied to cancer prevention and control, but the breadth, characteristics, and quality of these studies is not known.",
