      "status": "NOT_APPLICABLE",
      "chunk_id": "text_5",
      "quote": "The study was not registered in the International Prospective Register of Systematic Reviews (PROSPERO) as it was a methods review and did not assess health outcomes.",
      "reason": "This is a methods/characteristics review of system dynamics modeling studies, not a review of intervention effects, so planned comparisons in PICO format do not apply."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "Eligible designs (system dynamics modeling types) and topical scope (cancer prevention or control) are specified, but settings, populations, and other question-framework components are not detailed."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; ... and 4) were published within the last 10 years.",
      "reason": "Report characteristics are specified: peer-reviewed publication status, English language, and dissemination within the last 10 years."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "most studies included a computational system dynamics simulation model (n = 21; 66%), while the remaining studies (n = 11; 34%) used only diagramming approaches (referred to as diagram-only studies in this review)",
      "reason": "Synthesis groups (simulation vs diagram-only; topics mapped onto the cancer control continuum) are described in Results, but the Methods do not explicitly define these groups and link them to review objective comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "This search period was selected to reflect recent developments and current applications of system dynamics modeling related to cancer.",
      "reason": "A rationale is provided for the 10-year restriction on publication date; the Limitations section also explains the rationale for excluding non-cancer and pathogenesis-only studies."
    }
  ],
  "confidence": 85
}

